from pathlib import Path
import json,subprocess,html
root=Path(__file__).resolve().parents[2];out=root/'outputs/diarization';repo=Path('/Users/liangzhiquan/Desktop/S2T-UI')
data=json.loads((out/'final-comparison.json').read_text());view={}
for id,d in data['datasets'].items():
 if d.get('synthetic'):continue
 view[id]={'duration':d['duration'],'truth':d['truth'],'methods':d['methods']}
 ffmpeg=repo/'node_modules/ffmpeg-static/ffmpeg';dest=out/f'{id}.mp3'
 if not dest.exists():subprocess.run([str(ffmpeg),'-v','error','-i',str(repo/'tmp/voxconverse/wav/audio'/f'{id}.wav'),'-ac','1','-ar','16000','-b:a','64k','-threads','1',str(dest)],check=True)
page=r'''<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>長時間講者分離比較</title><style>body{margin:24px;background:#101923;color:#e6edf4;font:16px system-ui}h1{font-size:24px}select{max-width:100%}select,button{padding:8px;background:#253445;color:white;border:1px solid #708194;border-radius:6px}audio{width:min(700px,100%);margin:12px 0}main{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}section{background:#1c2938;padding:16px;border-radius:12px;min-width:0}.note{color:#bacada;line-height:1.7}.row{position:relative;height:24px;margin:4px 0;background:#12202e;overflow:hidden}.bar{position:absolute;height:100%;background:#336f9a;border:1px solid #8ac6ec;box-sizing:border-box;overflow:hidden;font-size:11px;white-space:nowrap}.truth .bar{background:#546631;border-color:#b5d67b}pre{white-space:pre-wrap;font-size:14px;line-height:1.6}.controls{display:flex;gap:8px;flex-wrap:wrap}#ref{margin:16px 0}a{color:#8bc9ff}@media(max-width:700px){body{margin:12px}main{grid-template-columns:1fr}}</style><h1>長時間講者分離比較</h1><p class="note">相同音訊，對照 RTTM 參考與不同方法。資料來自 tmp/VoxConverse，未驗證你的實際中文會議。顏色與對應參考使用整場最佳標籤對齊，僅供評分／核對，不代表模型認得姓名。此頁回放最終結果，不模擬即時輸出的延遲。</p><div class="controls"><label>音檔 <select id="dataset"></select></label><button id="start">開頭</button><button id="mid">中段</button><button id="end">尾段</button><button id="worst">目前左側最大錯配區</button></div><audio id="audio" controls preload="metadata"></audio><p id="clock"></p><section id="ref" class="truth"><h2>RTTM 參考</h2><div id="truth"></div></section><main><section><label>左側 <select id="left"></select></label><pre id="leftStats"></pre><div id="leftTimeline"></div><pre id="leftActive"></pre></section><section><label>右側 <select id="right"></select></label><pre id="rightStats"></pre><div id="rightTimeline"></div><pre id="rightActive"></pre></section></main><p class="note">時間軸顯示游標前後各 15 秒。8 人模型遇到 15 人素材屬超出容量；不要把強制只有 8 個標籤當作人數辨識正確。模型耗時為完整音檔未按真實時間餵入的牆鐘時間，不是首筆標籤延遲。<a href="研究與實驗報告.md">完整報告</a></p><script>const DATA=__DATA__;const $=id=>document.getElementById(id);const a=$('audio');for(const [id,d]of Object.entries(DATA))$('dataset').add(new Option(id+' · '+(d.duration/60).toFixed(1)+' 分鐘 · '+new Set(d.truth.map(t=>t.speaker)).size+' 人',id));let current;function setup(){current=DATA[$('dataset').value];for(const side of ['left','right']){const s=$(side);s.replaceChildren();for(const name of Object.keys(current.methods))s.add(new Option(name,name));}const right=Object.keys(current.methods).find(n=>n==='nemotron-v3-offline');if(right)$('right').value=right;a.src=$('dataset').value+'.mp3';draw();}function timeline(target,turns,time){const begin=Math.max(0,time-15),end=Math.min(current.duration,begin+30),labels=[...new Set(turns.filter(t=>t.end>begin&&t.start<end).map(t=>t.speaker))];target.replaceChildren();for(const label of labels){const title=document.createElement('small');title.textContent=label;target.append(title);const row=document.createElement('div');row.className='row';for(const t of turns.filter(t=>t.speaker===label&&t.end>begin&&t.start<end)){const bar=document.createElement('div');bar.className='bar';bar.style.left=100*(Math.max(begin,t.start)-begin)/(end-begin)+'%';bar.style.width=100*(Math.min(end,t.end)-Math.max(begin,t.start))/(end-begin)+'%';bar.textContent=t.start.toFixed(1)+'–'+t.end.toFixed(1);row.append(bar)}target.append(row)}}function draw(){if(!current)return;const time=a.currentTime||0;$('clock').textContent='游標 '+time.toFixed(2)+' 秒；參考正在說話：'+current.truth.filter(t=>t.start<=time&&t.end>time).map(t=>t.speaker).join('、');timeline($('truth'),current.truth,time);for(const side of ['left','right']){const m=current.methods[$(side).value],s=m.metrics;$(side+'Stats').textContent='人數 '+s.predictedSpeakers+'／參考 '+s.truthSpeakers+'\nDER '+s.DER+'% · 漏標 '+s.missPct+'% · 誤報 '+s.falseAlarmPct+'% · 錯配 '+s.confusionPct+'%';timeline($(side+'Timeline'),m.turns,time);$(side+'Active').textContent=m.turns.filter(t=>t.start<=time&&t.end>time).map(t=>t.speaker+' → 參考對齊 '+(s.mapping[t.speaker]||'未匹配')).join('\n')||'此時無標籤';}}$('dataset').onchange=setup;$('left').onchange=draw;$('right').onchange=draw;a.ontimeupdate=draw;$('start').onclick=()=>{a.currentTime=0;draw()};$('mid').onclick=()=>{a.currentTime=current.duration/2;draw()};$('end').onclick=()=>{a.currentTime=Math.max(0,current.duration-30);draw()};$('worst').onclick=()=>{const m=current.methods[$('left').value];let best=0,bestTime=0;for(let t=0;t<current.duration;t+=10){let wrong=0;for(let x=t;x<Math.min(t+20,current.duration);x+=.2){const R=new Set(current.truth.filter(v=>v.start<=x&&v.end>x).map(v=>v.speaker));const S=m.turns.filter(v=>v.start<=x&&v.end>x).map(v=>m.metrics.mapping[v.speaker]);wrong+=Math.max(R.size,S.length)-S.filter(v=>R.has(v)).length;}if(wrong>best){best=wrong;bestTime=t}}a.currentTime=bestTime;draw()};setup();</script></html>'''
(out/'speaker-replay.html').write_text(page.replace('__DATA__',json.dumps(view,ensure_ascii=False).replace('</','<\\/')))
print('Built speaker-replay.html',len(view),'recordings')
